<script setup lang="ts">
import { computed, ref } from 'vue'
import type { SearchOperatorSpace, SearchRecipeEntry } from '../types/search'

const props = defineProps<{ entries: SearchRecipeEntry[]; space?: SearchOperatorSpace }>()
const mode = ref('methods'), query = ref(''), selected = ref('')
const entries = computed(() => props.entries.filter(e => `${e.title} ${e.id}`.toLowerCase().includes(query.value.toLowerCase())))
const entry = computed(() => entries.value.find(e => e.id === selected.value) ?? entries.value[0])
const origin = (value: string) => (({ basic: '基础方法', literature: '文献方法', literature_adaptation: '文献方法适配' } as Record<string, string>)[value] ?? value)
const operator = (id: string) => props.space?.operators.find(o => o.id === id)?.title ?? id
const value = (v: unknown) => typeof v === 'object' ? JSON.stringify(v) : String(v)
const stage = (v: string) => (({ continuous: '连续信号', epochs: '试次', either: '连续信号 / 试次', same: '保持数据形态' } as Record<string, string>)[v] ?? v)
const editLabel = (v: string) => (({ set_parameter: '调整参数', swap_adjacent: '相邻换序', insert_operator: '插入算子', remove_operator: '删除算子', set_adaptation: '调整个体适配' } as Record<string, string>)[v] ?? v)
const adaptation = (v: string) => (({ none: '保持物理幅值', subject_scale: '逐被试尺度统一', euclidean_alignment: '逐被试无标签欧氏对齐', conditional_alignment: '按诊断条件逐被试对齐' } as Record<string, string>)[v] ?? v)
const webLink = (v: string) => /^https?:\/\//i.test(v)
</script>

<template>
  <section class="method-explorer" aria-label="方法与算子探索空间">
    <div class="explorer-nav"><button v-for="(label, key) in { methods: '方法与候选', operators: '算子与参数', priors: '顺序与科学先验' }" :key="key" :aria-pressed="mode === key" @click="mode = key">{{ label }}</button></div>
    <div v-if="mode === 'methods'" class="method-layout">
      <aside>
        <label class="search-label">查找方法<input v-model="query" type="search" placeholder="方法名称或编号" /></label>
        <nav aria-label="候选配方"><button v-for="item in entries" :key="item.id" :aria-pressed="entry?.id === item.id" @click="selected = item.id"><strong>{{ item.title }}</strong><small>{{ item.parent_id ? '探索候选' : origin(item.origin) }} · {{ item.recipe.nodes.length }} 个算子</small></button></nav>
      </aside>
      <article v-if="entry" class="recipe-detail">
        <header><span class="kicker">{{ origin(entry.origin) }}</span><h3>{{ entry.title }}</h3><p class="muted">{{ entry.id }}</p></header>
        <p v-if="entry.parent_id" class="lineage">父方案：<button @click="selected = entry.parent_id; query = ''">{{ props.entries.find(e => e.id === entry?.parent_id)?.title ?? entry.parent_id }}</button></p>
        <ol class="operator-flow"><li v-for="(node, index) in entry.recipe.nodes" :key="node.id"><span class="step-number">{{ index + 1 }}</span><div><strong>{{ operator(node.operator) }}</strong><dl v-if="Object.keys(node.parameters).length"><template v-for="(v, name) in node.parameters" :key="name"><dt>{{ name }}</dt><dd>{{ value(v) }}</dd></template></dl><small v-else class="muted">按共同数据与输出合同执行</small></div></li></ol>
        <div class="adaptation"><strong>个体表示</strong><span>{{ adaptation(entry.recipe.adaptation.adaptation) }}<template v-if="entry.recipe.adaptation.adaptation === 'conditional_alignment'"> · 阈值 {{ entry.recipe.adaptation.alignment_threshold }}</template></span></div>
        <section v-if="entry.edits.length"><h4>本次探索的改动</h4><ul><li v-for="(edit, i) in entry.edits" :key="i"><strong>{{ editLabel(edit.action) }}</strong><span class="muted">{{ Object.entries(edit).filter(([k]) => k !== 'action').map(([k,v]) => `${k}: ${value(v)}`).join(' · ') }}</span></li></ul></section>
        <section v-if="entry.deviations.length"><h4>适用条件与方法适配</h4><ul><li v-for="note in entry.deviations" :key="note">{{ note }}</li></ul></section>
        <section v-if="Object.keys(entry.prior_challenges).length"><h4>需要实验证明的先验挑战</h4><p v-for="(reason, key) in entry.prior_challenges" :key="key"><strong>{{ key }}</strong> {{ reason }}</p></section>
        <section v-if="entry.evidence_ids.length"><h4>方法依据</h4><p v-for="key in entry.evidence_ids" :key="key"><template v-if="space?.evidence[key]"><a v-if="webLink(space.evidence[key].source_url)" :href="space.evidence[key].source_url" target="_blank" rel="noopener noreferrer">{{ space.evidence[key].locator }} ↗</a><span v-else>{{ space.evidence[key].locator }}</span><small class="muted">{{ space.evidence[key].text }}</small></template></p></section>
      </article>
      <p v-else class="empty">没有匹配的配方记录。</p>
    </div>
    <div v-else-if="mode === 'operators'" class="contract-list"><article v-for="op in space?.operators ?? []" :key="op.id"><header><h3>{{ op.title }}</h3><span class="pill">{{ op.required ? '固定保留' : '可选算子' }}</span></header><p class="muted">{{ stage(op.input_stage) }} → {{ stage(op.output_stage) }}</p><p v-if="op.requires.length">前提：{{ op.requires.join('、') }}</p><dl class="domains"><template v-for="(domain, key) in op.domains" :key="key"><dt>{{ key }}</dt><dd><strong>{{ domain.kind === 'choice' ? domain.choices?.map(value).join(' / ') : `${domain.minimum}–${domain.maximum} ${domain.unit}` }}</strong><small>{{ domain.rationale }} · {{ domain.origin === 'literature' ? '文献依据' : '数学、实现或工程范围' }}</small></dd></template></dl><p v-if="op.input_highpass" class="muted">输入频谱前提：{{ op.input_highpass.rationale }}</p><p v-for="rule in op.separations ?? []" :key="rule.upper_parameter" class="muted">{{ rule.upper_parameter }} − {{ rule.lower_parameter }} ≥ {{ rule.minimum }}：{{ rule.rationale }}</p></article></div>
    <div v-else class="contract-list"><p class="muted">硬约束保证配方可执行；软先验允许挑战，但需记录理由及实测结果。每条规则只在其条件下适用。</p><article v-for="prior in space?.priors ?? []" :key="prior.id"><header><h3>{{ prior.id }}</h3><span class="pill" :class="prior.strength">{{ prior.strength === 'hard' ? '必须满足' : '可挑战的先验' }}</span></header><p>{{ prior.rationale }}</p><small class="muted">适用条件：{{ prior.condition }}</small><p v-for="key in prior.evidence_ids" :key="key"><a v-if="space?.evidence[key] && webLink(space.evidence[key].source_url)" :href="space.evidence[key].source_url" target="_blank" rel="noopener noreferrer">{{ space.evidence[key].locator }} ↗</a></p></article></div>
  </section>
</template>

<style scoped>
.method-explorer{color:#294638;font-size:13px}.explorer-nav{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:20px}button{font:inherit;cursor:pointer;color:inherit;background:white;border:1px solid #d9e4dc;border-radius:7px;padding:8px 12px}button[aria-pressed=true]{background:#edf5ef;border-color:#83a990}.method-layout{display:grid;grid-template-columns:240px minmax(0,1fr);border:1px solid #e0e8e2;border-radius:10px;overflow:hidden;min-height:350px}.method-layout aside{border-right:1px solid #e0e8e2;padding:14px;background:#f9fbf9}.search-label{display:grid;gap:7px;font-size:12px;color:#728779}input{border:1px solid #d9e4dc;border-radius:6px;padding:9px;min-width:0;width:100%;box-sizing:border-box}nav{display:grid;gap:7px;max-height:54vh;overflow:auto;margin-top:13px}nav button{text-align:left;overflow-wrap:anywhere}nav small{display:block;margin-top:5px;color:#7b8b80}.recipe-detail{padding:24px;max-height:65vh;overflow:auto;min-width:0}.kicker{font-size:10px;letter-spacing:.08em;color:#728779}h3{font-size:17px;margin:6px 0}h4{font-size:13px;margin:20px 0 10px}.muted{color:#7c8c81;font-size:12px;overflow-wrap:anywhere}.lineage{padding:10px 0;border-bottom:1px solid #e7eee8}.lineage button{border:0;padding:0;color:#37765a;text-decoration:underline}.operator-flow{list-style:none;padding:0;margin:24px 0;display:grid;gap:20px}.operator-flow li{display:flex;gap:14px;position:relative}.step-number{border:1px solid #caddcf;background:#f0f6f1;border-radius:50%;width:28px;height:28px;display:grid;place-items:center;flex-shrink:0;font-size:11px}.operator-flow li:not(:last-child):before{content:'';position:absolute;left:14px;top:31px;bottom:-17px;width:1px;background:#d8e4db}dl{display:flex;flex-wrap:wrap;gap:5px 10px;margin:7px 0;font-size:12px}dt{color:#829084}dd{margin:0 12px 0 0}.adaptation{background:#eff5f0;border-radius:8px;padding:13px;display:flex;flex-wrap:wrap;gap:12px}.recipe-detail ul{padding-left:18px}.recipe-detail li{margin-bottom:9px;overflow-wrap:anywhere}.recipe-detail li span{display:block;margin-top:4px}a{color:#367653;text-decoration:none}a:hover{text-decoration:underline}p small{display:block;margin-top:7px}.contract-list{max-height:65vh;overflow:auto;padding-right:8px}.contract-list article{border:1px solid #e1e9e3;padding:18px;border-radius:9px;margin:12px 0}.contract-list header{display:flex;justify-content:space-between;align-items:center;gap:15px}.contract-list h3{font-size:14px}.pill{font-size:10px;background:#eff4ef;color:#738477;padding:4px 8px;border-radius:20px;white-space:nowrap}.pill.hard{color:#6c653f;background:#f5f2e8}.domains{display:grid;grid-template-columns:minmax(90px,auto) 1fr;gap:12px;margin-top:18px}.domains small{display:block;color:#819085;margin-top:5px}.empty{padding:40px;text-align:center;color:#819085}@media(max-width:850px){.method-layout{grid-template-columns:1fr}.method-layout aside{border-right:0;border-bottom:1px solid #e0e8e2}.method-layout nav{max-height:150px;grid-template-columns:repeat(2,minmax(0,1fr))}.recipe-detail{padding:18px}}
</style>
